Import ListNotations. Import AX2. Import AX2B. Import AX2S.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Open Scope Z_scope.

Module CCR.
Abbreviation RSEGS := PML.RSEGS.
Abbreviation mem := (word -> option byte).
Definition box (X : Prop) : Prop := ltac2:(Rpl.RP.run_k (rplG ()) 1 "U0;LX;Rpr1;").
Lemma boxed : forall {X : Prop}, X -> box X.
Proof. ltac2:(Rpl.RP.run_k (rplG ()) 0 "S0;LX;RpLx;Rr1;r1;").
